import { spawn } from 'node:child_process';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';

// #3415. run-hook.mjs gives stdin 100ms, then runs the hook against {} and exits
// 0. That is indistinguishable from a successful no-op, so a producer merely SLOW
// to write its first byte silently measures nothing. Both sibling degraded paths
// (stdin truncated, truncated JSON unparsable) already warn; this one did not.
//
// These tests are a matched pair. The slow case is the positive control and FAILS
// on the pre-fix code, where no warning is emitted. The fast case is the negative
// control: it proves the warning is not emitted spuriously on every run, which is
// the way a fix like this goes wrong.

const RUN_HOOK = join(__dirname, '../../../bin/run-hook.mjs');
const HOOK = 'pretool/bash/dangerous-command-blocker';
const WARNING = /stdin delivered 0 bytes in 100ms/;

const PAYLOAD = JSON.stringify({
  hook_event_name: 'PreToolUse',
  session_id: '00000000-0000-4000-8000-000000000000',
  cwd: '/tmp',
  tool_name: 'Bash',
  tool_input: { command: 'echo hi' },
});

/** Spawn run-hook.mjs and write the payload after `delayMs`. Never pipes. */
function runWithDelay(delayMs: number): Promise<{ stderr: string; code: number | null }> {
  return new Promise((resolve) => {
    const child = spawn('node', [RUN_HOOK, HOOK], {
      stdio: ['pipe', 'pipe', 'pipe'],
      env: { ...process.env, CLAUDE_PROJECT_DIR: '/tmp' },
    });
    let stderr = '';
    child.stderr.on('data', (c) => {
      stderr += String(c);
    });
    child.stdout.resume();

    const timer = setTimeout(() => {
      child.stdin.write(PAYLOAD);
      child.stdin.end();
    }, delayMs);

    child.on('close', (code) => {
      clearTimeout(timer);
      resolve({ stderr, code });
    });
  });
}

describe('#3415 run-hook.mjs stdin timeout is observable', () => {
  it('WARNS when a piped stdin delivers nothing inside the 100ms window', async () => {
    const { stderr } = await runWithDelay(300);
    expect(stderr).toMatch(WARNING);
    // the message has to be actionable, not just present
    expect(stderr).toMatch(/EMPTY payload/);
    // toContain, not a hand-built RegExp: escaping only `/` is incomplete
    // (CodeQL js/incomplete-sanitization) and unnecessary, since `/` needs no
    // escape in the RegExp constructor. A substring check is what was meant.
    expect(stderr).toContain(HOOK);
  }, 15000);

  it('stays SILENT when the payload arrives in time (no spurious warning)', async () => {
    const { stderr } = await runWithDelay(0);
    expect(stderr).not.toMatch(WARNING);
  }, 15000);

  // Found while fixing the above, and more severe than it. The >512KB truncation
  // guard (#620, image pastes) interpolated a bare `name`, and there is no local
  // `name` at that point, so in ESM it was a ReferenceError. The write sits
  // OUTSIDE the try/catch below it, so the guard crashed the hook with an uncaught
  // exception instead of degrading. Pre-fix this test sees a non-zero exit and a
  // ReferenceError on stderr.
  it('degrades rather than CRASHES when stdin exceeds the 512KB cap', async () => {
    const oversized = JSON.stringify({
      hook_event_name: 'PreToolUse',
      session_id: '00000000-0000-4000-8000-000000000000',
      cwd: '/tmp',
      tool_name: 'Bash',
      tool_input: { command: `echo ${'A'.repeat(600 * 1024)}` },
    });

    const { stderr, code } = await new Promise<{ stderr: string; code: number | null }>(
      (resolve) => {
        const child = spawn('node', [RUN_HOOK, HOOK], {
          stdio: ['pipe', 'pipe', 'pipe'],
          env: { ...process.env, CLAUDE_PROJECT_DIR: '/tmp' },
        });
        let err = '';
        child.stderr.on('data', (c) => {
          err += String(c);
        });
        child.stdout.resume();
        // EPIPE here is the guard WORKING: run-hook.mjs calls
        // process.stdin.destroy() the moment stdin passes the cap, so this
        // parent is mid-write to a closed pipe. Swallowing it is correct;
        // without this the test passes locally on pipe-buffer timing and
        // throws EPIPE in CI, which is what it did on the first run.
        child.stdin.on('error', (e: NodeJS.ErrnoException) => {
          if (e.code !== 'EPIPE') throw e;
        });
        child.stdin.write(oversized, () => {
          child.stdin.end();
        });
        child.on('close', (c) => resolve({ stderr: err, code: c }));
      },
    );

    expect(stderr).not.toMatch(/ReferenceError/);
    expect(stderr).toMatch(/stdin truncated at/);
    // toContain, not a hand-built RegExp: escaping only `/` is incomplete
    // (CodeQL js/incomplete-sanitization) and unnecessary, since `/` needs no
    // escape in the RegExp constructor. A substring check is what was meant.
    expect(stderr).toContain(HOOK);
    expect(code).toBe(0);
  }, 20000);

  it('still exits 0 in both cases, so the guard never breaks a session', async () => {
    const slow = await runWithDelay(300);
    const fast = await runWithDelay(0);
    expect(slow.code).toBe(0);
    expect(fast.code).toBe(0);
  }, 20000);
});

// ---------------------------------------------------------------------------
// The conjunction of the two conditions above, which neither test covers.
//
// The `data` handler set `stdinClosed = true` without ever reading it, while its
// `end` and `error` siblings both guarded on it. So when the 100ms timeout had
// ALREADY run the hook (#3415, slow producer) and a >512KB payload then arrived
// (#620, image paste), the truncation branch ran it a SECOND time and appended a
// second envelope. Combined stdout became `{...}\n{...}\n` — starts with `{`,
// fails JSON.parse.
//
// CC 2.1.248 promoted that from "silently treated as plain text" to a reported
// hook error whose result is discarded, so the defect went from invisible to
// operator-visible without changing here.
//
// These assert on STDOUT. The tests above all call `child.stdout.resume()` and
// assert only on stderr and the exit code, which is why a stdout defect could
// live behind three green tests: they were structurally unable to see it.
// ---------------------------------------------------------------------------

/** Spawn run-hook.mjs, write `sizeKB` after `delayMs`, and CAPTURE stdout. */
function runCapturingStdout(
  delayMs: number,
  sizeKB: number,
): Promise<{ stdout: string; envelopes: number; parses: boolean }> {
  return new Promise((resolve) => {
    const child = spawn('node', [RUN_HOOK, HOOK], {
      stdio: ['pipe', 'pipe', 'pipe'],
      env: { ...process.env, CLAUDE_PROJECT_DIR: '/tmp' },
    });
    let stdout = '';
    child.stdout.on('data', (c) => {
      stdout += String(c);
    });
    child.stderr.resume();

    // The oversized cases make run-hook.mjs call process.stdin.destroy() while this
    // side is still writing, so the write EPIPEs. Without a listener that becomes an
    // unhandled 'error' on the stream, and vitest exits non-zero AFTER reporting every
    // test as passed — which is what it did on CI while passing locally, because the
    // race resolves differently on a slower machine. EPIPE here is the expected
    // outcome of the very behaviour under test, not a failure.
    child.stdin.on('error', () => {
      /* EPIPE: the hook closed stdin at the 512KB cap, as designed */
    });

    const big = JSON.stringify({
      ...JSON.parse(PAYLOAD),
      pad: 'x'.repeat(sizeKB * 1024),
    });
    const timer = setTimeout(() => {
      try {
        child.stdin.write(big);
        child.stdin.end();
      } catch {
        /* stream already destroyed by the cap; the assertions read stdout regardless */
      }
    }, delayMs);

    child.on('close', () => {
      clearTimeout(timer);
      let parses = true;
      try {
        JSON.parse(stdout.trim());
      } catch {
        parses = false;
      }
      resolve({ stdout, envelopes: (stdout.match(/\{"continue"/g) ?? []).length, parses });
    });
  });
}

describe('run-hook.mjs emits exactly one envelope on stdout', () => {
  // The positive control: FAILS on the pre-fix code with envelopes=2 and parses=false.
  it('does not double-emit when a >512KB payload lands AFTER the stdin timeout', async () => {
    const { envelopes, parses, stdout } = await runCapturingStdout(400, 600);
    expect(envelopes, `stdout was: ${JSON.stringify(stdout.slice(0, 200))}`).toBe(1);
    expect(parses).toBe(true);
  }, 15000);

  // Negative controls: each condition ALONE was always fine, and must stay fine —
  // that is how a fix like this goes wrong (over-guarding and emitting nothing).
  it('still emits exactly one envelope for an oversized payload with no delay', async () => {
    const { envelopes, parses } = await runCapturingStdout(0, 600);
    expect(envelopes).toBe(1);
    expect(parses).toBe(true);
  }, 15000);

  it('still emits exactly one envelope for a small payload after a delay', async () => {
    const { envelopes, parses } = await runCapturingStdout(400, 1);
    expect(envelopes).toBe(1);
    expect(parses).toBe(true);
  }, 15000);
});
